import{_ as e,o as t,c as l,a2 as r}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"📝 更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"guide/changelog.md","filePath":"guide/changelog.md","lastUpdated":1793540283000}'),i={name:"guide/changelog.md"};function o(n,a,u,s,h,g){return t(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="📝-更新日志" tabindex="-1">📝 更新日志 <a class="header-anchor" href="#📝-更新日志" aria-label="Permalink to &quot;📝 更新日志&quot;">​</a></h1><p>各版本的下载地址见 <a href="https://github.com/XnneHangLab/yutto-uiya/releases" target="_blank" rel="noreferrer">GitHub Releases</a>。</p><h2 id="v2-3-3-2026-11-01" tabindex="-1">v2.3.3（2026-11-01） <a class="header-anchor" href="#v2-3-3-2026-11-01" aria-label="Permalink to &quot;v2.3.3（2026-11-01）&quot;">​</a></h2><p><strong>修复多 P 下载覆盖，支持播放地址展开合集</strong></p><ul><li>修复多 P 视频列表显示正确但下载仍使用同一文件名的问题，下载时按分 P 名称保存（<a href="https://github.com/XnneHangLab/yutto-uiya/pull/109" target="_blank" rel="noreferrer">#109</a>）；</li><li>内核升级至 uiya-yutto 0.3.4，同步上游更新（<a href="https://github.com/XnneHangLab/yutto-uiya/pull/110" target="_blank" rel="noreferrer">#110</a>）；</li><li>支持直接从合集成员的 BV 播放地址解析所属合集，并展开成员视频内的各个分 P；没有合集信息的多 P 投稿继续按当前 BV 解析；</li><li>更新合集解析排查说明，补充内核升级、重启 server 和合集入口排查步骤。</li></ul><h2 id="v2-3-2-2026-10-17" tabindex="-1">v2.3.2（2026-10-17） <a class="header-anchor" href="#v2-3-2-2026-10-17" aria-label="Permalink to &quot;v2.3.2（2026-10-17）&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">多 P 下载覆盖风险</p><p>此版本仅修复了解析列表的标题显示，下载时仍可能因同名覆盖其他分 P。安装附件已撤下，请升级至 2.3.3，并核对此前下载的多 P 文件数量和内容。</p></div><p><strong>多 P 标题与编码偏好修复</strong></p><ul><li>修复普通多 P、混合列表及同名分组中的分 P 标题显示（<a href="https://github.com/XnneHangLab/yutto-uiya/pull/103" target="_blank" rel="noreferrer">#103</a>）；</li><li>视频编码明确提供 H.264（兼容优先）和 AV1（体积优先），不可用时自动回退（<a href="https://github.com/XnneHangLab/yutto-uiya/pull/104" target="_blank" rel="noreferrer">#104</a>、<a href="https://github.com/XnneHangLab/yutto-uiya/pull/105" target="_blank" rel="noreferrer">#105</a>）；</li><li>Windows 与 macOS 便携包内置 Python 环境、下载引擎和 FFmpeg（<a href="https://github.com/XnneHangLab/yutto-uiya/pull/100" target="_blank" rel="noreferrer">#100</a>）。</li></ul><h2 id="v2-3-1-2026-08-19" tabindex="-1">v2.3.1（2026-08-19） <a class="header-anchor" href="#v2-3-1-2026-08-19" aria-label="Permalink to &quot;v2.3.1（2026-08-19）&quot;">​</a></h2><p><strong>实际资源与番剧详情</strong></p><ul><li>新增视频编码偏好：可主动选择 AV1；自动模式继续采用内核的兼容优先与回退策略（<a href="https://github.com/XnneHangLab/yutto-uiya/issues/96" target="_blank" rel="noreferrer">#96</a>）；</li><li>下载卡片与控制台显示最终选择的画质、编码、分辨率和转码动作（<a href="https://github.com/XnneHangLab/yutto-uiya/issues/97" target="_blank" rel="noreferrer">#97</a>）；</li><li>番剧详情补全发布方、剧情简介、标签、发布时间和分集时长（<a href="https://github.com/XnneHangLab/yutto-uiya/issues/98" target="_blank" rel="noreferrer">#98</a>）；</li><li>内核升级至 uiya-yutto 0.3.2，支持结构化的最终媒体选择事件。</li></ul><h2 id="v2-3-0-2026-08-12" tabindex="-1">v2.3.0（2026-08-12） <a class="header-anchor" href="#v2-3-0-2026-08-12" aria-label="Permalink to &quot;v2.3.0（2026-08-12）&quot;">​</a></h2><p><strong>解析与网络体验修复</strong></p><ul><li>恢复 PGC / 番剧分集标题，解析结果不再显示通用视频标题（<a href="https://github.com/XnneHangLab/yutto-uiya/issues/85" target="_blank" rel="noreferrer">#85</a>）；</li><li>封面抓取失败时提供更可用的诊断信息（<a href="https://github.com/XnneHangLab/yutto-uiya/issues/87" target="_blank" rel="noreferrer">#87</a>）；</li><li>默认使用直连；需要时仍可启用系统或环境代理（<a href="https://github.com/XnneHangLab/yutto-uiya/issues/88" target="_blank" rel="noreferrer">#88</a>）；</li><li>内核升级至 uiya-yutto 0.3.0（<a href="https://github.com/XnneHangLab/yutto-uiya/issues/91" target="_blank" rel="noreferrer">#91</a>）；</li><li>明确封面与视频、音频同时下载时内嵌，单独下载时另存（<a href="https://github.com/XnneHangLab/yutto-uiya/issues/93" target="_blank" rel="noreferrer">#93</a>）。</li></ul><h2 id="v2-2-1-2026-07-19" tabindex="-1">v2.2.1（2026-07-19） <a class="header-anchor" href="#v2-2-1-2026-07-19" aria-label="Permalink to &quot;v2.2.1（2026-07-19）&quot;">​</a></h2><p><strong>FFmpeg 路径修复与内核升级</strong></p><ul><li>修复自定义 FFmpeg 路径：环境检查与 serve 现在使用同一个可执行文件，不再依赖文件名必须为 <code>ffmpeg</code>（<a href="https://github.com/XnneHangLab/yutto-uiya/issues/77" target="_blank" rel="noreferrer">#77</a>）；</li><li>音频-only mp3/flac 转码逻辑下沉到 uiya-yutto 内核的 <code>resolve_audio_save_codec</code>，前端不再显式覆盖编码（<a href="https://github.com/XnneHangLab/yutto-uiya/issues/74" target="_blank" rel="noreferrer">#74</a>）；</li><li>内核升级至 uiya-yutto 0.2.4；</li><li>项目以 AGPL-3.0-only 许可证发布。</li></ul><h2 id="v2-2-0-2026-07-18" tabindex="-1">v2.2.0（2026-07-18） <a class="header-anchor" href="#v2-2-0-2026-07-18" aria-label="Permalink to &quot;v2.2.0（2026-07-18）&quot;">​</a></h2><p><strong>迁移到常驻 yutto server</strong> —— 解析与下载不再逐次启动子进程抓日志，改由一个随应用 自动启停的后台 server 驱动，结构化事件实时回传。</p><ul><li>收藏夹 / 合集解析大幅提速，列表边解析边逐条平滑出现；</li><li>下载卡片显示阶段（解析中 / 写入附件 / 下载中 / 后处理中）与实时进度条 （百分比 · 已下载 / 总量 · 速率），不再需要去控制台看进度；</li><li>下载队列串行执行，显著降低触发 B 站风控的概率；</li><li>修复仅音频 MP3 / FLAC 下载在合并阶段必然失败的问题（现在自动转码）；</li><li>保存设置会自动重启 server，下载目录 / FFmpeg / Python 的修改立即生效；</li><li>内核升级至 uiya-yutto 0.2.1。</li></ul><div class="warning custom-block"><p class="custom-block-title">升级后需要知道的变化</p><ul><li><strong>画质菜单</strong>总是显示完整档位（最高 8K），实际画质下载时自动降级，选高了不会失败 —— 详见 <a href="/troubleshooting/quality-auto-downgrade.html">画质菜单与批量下载画质说明</a>；</li><li><strong>队列串行</strong>是刻意设计（防风控），同一时刻只有一个任务在下载，其余显示「排队中」；</li><li><strong>正在解析 / 下载时保存设置会中断这些任务</strong>（设置页会先提示）；</li><li>之前用 MP3 / FLAC 仅音频下载失败过的用户，现在可以再试了；</li><li><strong>疑难解答</strong>从应用内移到了本文档站点，应用内的入口会直接打开本站。</li></ul></div><h2 id="v2-1-0-2026-07-11" tabindex="-1">v2.1.0（2026-07-11） <a class="header-anchor" href="#v2-1-0-2026-07-11" aria-label="Permalink to &quot;v2.1.0（2026-07-11）&quot;">​</a></h2><p><strong>批量解析提速</strong></p><ul><li>内核升级至 uiya-yutto 0.1.0，合集 / 收藏夹批量解析并发执行，等待时间大幅缩短；</li><li>新增「解析并发数」设置项；</li><li>批量解析时单个视频失败不再中断整体任务；</li><li>VitePress 文档站点上线。</li></ul><h2 id="v2-0-2-2026-07-05" tabindex="-1">v2.0.2（2026-07-05） <a class="header-anchor" href="#v2-0-2-2026-07-05" aria-label="Permalink to &quot;v2.0.2（2026-07-05）&quot;">​</a></h2><p><strong>下载目录可配置与疑难解答</strong></p><ul><li>下载目录可独立配置，不再绑定根目录；</li><li>应用内疑难解答页面（v2.2.0 起移至本文档站点）；</li><li>音频格式选择（M4A / MP3 / FLAC / WAV）；</li><li>非首页懒加载，优化启动速度。</li></ul><h2 id="v2-0-1-2026-04-16" tabindex="-1">v2.0.1（2026-04-16） <a class="header-anchor" href="#v2-0-1-2026-04-16" aria-label="Permalink to &quot;v2.0.1（2026-04-16）&quot;">​</a></h2><p><strong>资源选择器与多平台构建</strong></p><ul><li>下载资源选择器（视频 / 音频 / 封面 / 字幕 / 弹幕）；</li><li>音频画质选项；</li><li>平台信息展示与一键 uv sync；</li><li>多平台 Release 构建流水线。</li></ul><h2 id="v2-0-0-2026-04-12" tabindex="-1">v2.0.0（2026-04-12） <a class="header-anchor" href="#v2-0-0-2026-04-12" aria-label="Permalink to &quot;v2.0.0（2026-04-12）&quot;">​</a></h2><p><strong>从 Streamlit 迁移至 Tauri</strong></p><ul><li>全新 Tauri 2 + React 桌面客户端；</li><li>全局快捷键呼出窗口；</li><li>合集 / 收藏夹批量解析与下载；</li><li>实时控制台日志；</li><li>扫码登录。</li></ul>',34)])])}const p=e(i,[["render",o]]);export{c as __pageData,p as default};
